-- Gerado por scripts/generate-seed.ts a partir de src/data/catalog.ts. Não edite à mão.
-- Pode rodar de novo. Trilhas, cursos, módulos e aulas: só cria o que falta, para não
-- desfazer o que o admin editou no app. Níveis, recompensas, lives e Escudo: atualiza.

on conflict (id) do nothing;

on conflict (level) do update set name = excluded.name, min_points = excluded.min_points, min_givers = excluded.min_givers, meaning = excluded.meaning;

on conflict (id) do nothing;

on conflict (id) do update set track_id = excluded.track_id, kind = excluded.kind, title = excluded.title, description = excluded.description, cost = excluded.cost, min_level = excluded.min_level, course_id = excluded.course_id;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (lesson_id) do nothing;

on conflict (id) do update set name = excluded.name;

on conflict (product_id, course_id) do nothing;

-- Produtos antigos (assinatura geral e venda de curso avulso da trilha) saem da vitrine.
update public.products p set active = false where p.id = 'assinatura-vivah'
  or exists (select 1 from public.courses c where c.id = p.id and not c.low_ticket);
on conflict (id) do nothing;

on conflict (id) do update set area = excluded.area, prompt = excluded.prompt, options = excluded.options, sort = excluded.sort;

on conflict (id) do update set title = excluded.title, description = excluded.description, track_id = excluded.track_id, host = excluded.host, starts_at = excluded.starts_at, ends_at = excluded.ends_at, youtube_id = excluded.youtube_id, replay_until = excluded.replay_until;

on conflict (id) do update set publish_date = excluded.publish_date, title = excluded.title, summary = excluded.summary, duration_min = excluded.duration_min;
